<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__).'/Support/jobs_extensions_schema_assertions.php';require dirname(__DIR__,2).'/app/autoload.php';
use FMonitor2\InstallationProcess\JobsSchemaMigration;
assertSameValue(true,class_exists(JobsSchemaMigration::class),'INTENTIONAL_RED: v23 Jobs migration extension seam exists');
$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$token=bin2hex(random_bytes(5));$names=['t_jobs_ext_'.$token,'t_jobs_ext_bad_'.$token];$admin=new mysqli($host,$user,$password,'',$port);foreach($names as$name)$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$user,$password,$names[0],$port);$bad=new mysqli($host,$user,$password,$names[1],$port);$p='ext_';
function jesRows(mysqli$db,string$p):array{$out=[];foreach(['fm2_outbox_intents','fm2_outbox_attempt_events','fm2_scheduler_slots','fm2_worker_heartbeats']as$table)$out[$table]=$db->query("SELECT * FROM `{$p}{$table}` ORDER BY 1")->fetch_all(MYSQLI_ASSOC);return$out;}
try{$result=JobsSchemaMigration::apply($db,$p);assertSameValue([true,23],[$result['applied'],$result['schemaVersion']],'clean v23 creates foundation plus extensions');jobsAssertExtensionsSchema($db,$p);JobsSchemaMigration::apply($db,'other_');jobsAssertExtensionsSchema($db,'other_');$db->query("INSERT INTO `{$p}fm2_outbox_intents`(domain_event_id,channel,template_reference,payload_version,data_json,fingerprint,status,created_at_utc)VALUES('event-1','email','template-v1',1,'{}',REPEAT('a',64),'pending','2026-09-09T10:00:00.000000Z')");$db->query("INSERT INTO `{$p}fm2_worker_heartbeats`VALUES('worker-1','2026-09-09T10:00:00.000000Z')");$db->query("INSERT INTO other_fm2_worker_heartbeats VALUES('other-worker','2026-09-09T09:00:00.000000Z')");$before=jesRows($db,$p);$otherBefore=jesRows($db,'other_');assertSameValue(false,JobsSchemaMigration::apply($db,$p)['applied'],'compatible populated all-six repeat no-op');assertSameValue([$before,$otherBefore],[jesRows($db,$p),jesRows($db,'other_')],'repeat and prefix isolation preserve exact extension rows');
    $bad->query("CREATE TABLE `{$p}fm2_outbox_attempt_events`(sentinel INT PRIMARY KEY)ENGINE=InnoDB");$bad->query("INSERT INTO `{$p}fm2_outbox_attempt_events`VALUES(71)");$bad->query('CREATE TABLE ambient_keep(id INT PRIMARY KEY)ENGINE=InnoDB');$bad->query('INSERT INTO ambient_keep VALUES(9)');$inventory=static fn(mysqli$c):array=>array_column($c->query('SHOW TABLES')->fetch_all(MYSQLI_NUM),0);$badBefore=[$inventory($bad),$bad->query("SELECT * FROM `{$p}fm2_outbox_attempt_events`")->fetch_all(MYSQLI_ASSOC),$bad->query('SELECT * FROM ambient_keep')->fetch_all(MYSQLI_ASSOC)];$rejected=false;try{JobsSchemaMigration::apply($bad,$p);}catch(RuntimeException){$rejected=true;}assertSameValue(true,$rejected,'incompatible extension second member rejects');assertSameValue($badBefore,[$inventory($bad),$bad->query("SELECT * FROM `{$p}fm2_outbox_attempt_events`")->fetch_all(MYSQLI_ASSOC),$bad->query('SELECT * FROM ambient_keep')->fetch_all(MYSQLI_ASSOC)],'whole six-table preflight creates nothing and preserves conflict/ambient');echo"PASS: DURABLE-JOBS-EXTENSIONS-SCHEMA-001 exact v23 extension family\n";
}finally{$bad->close();$db->close();foreach($names as$name)$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}
